/* invite */
.iv{position:relative;max-width:420px;padding:16px;overflow:visible!important}
.iv-head .t{font-size:15px;font-weight:600}
.iv-head .d{margin-top:2px;font-size:13px;color:var(--text-dim)}
.iv-row{display:flex;gap:8px;margin-top:14px}
.iv-field{position:relative;flex:1;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:5px;min-height:40px;padding:5px 8px;background:var(--panel);border:1px solid var(--icon-line);cursor:text;transition:border-color .2s,box-shadow .2s}
.iv-field:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-bg)}
.iv-chips{display:contents}
.iv-chip{display:inline-flex;align-items:center;gap:5px;height:26px;padding:0 4px 0 3px;background:var(--chip);font-size:12.5px;font-weight:500;animation:iconin .3s var(--ease) both}
.iv-chip .dz-av{width:20px;height:20px}
.iv-chip button{width:18px;height:18px;display:grid;place-items:center;color:var(--muted)}
.iv-chip button:hover{color:var(--text)}
.iv-field input{flex:1;min-width:120px;height:26px;background:transparent;border:0;outline:0;font:inherit;font-size:13.5px;color:var(--text)}
.iv-field input::placeholder{color:var(--muted)}
.iv-perm{flex:none;display:inline-flex;align-items:center;gap:4px;height:40px;padding:0 10px 0 12px;border:1px solid var(--icon-line);background:var(--panel);font-size:13px;font-weight:500;color:var(--text);white-space:nowrap}
.iv-perm .ms{color:var(--muted)}
.iv-sug{position:absolute;left:16px;right:16px;z-index:5;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px);transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.iv-sug.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.iv-s{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;text-align:left;transition:background-color .15s}
.iv-s.act{background:var(--chip)}
.iv-s .dz-av{width:28px;height:28px}
.iv-s .n{font-size:13.5px;font-weight:500;color:var(--text)}
.iv-s .e{font-size:12px;color:var(--muted)}
.iv-ini{width:28px;height:28px;flex:none;display:grid;place-items:center;border-radius:50%;background:var(--chip);color:var(--text-dim);font-size:12px;font-weight:600}
.iv-sec{margin:16px 0 6px;font-size:12px;font-weight:600;color:var(--muted)}
.iv-p{display:flex;align-items:center;gap:10px;padding:7px 0}
.iv-p .dz-av,.iv-p .iv-ini{width:32px;height:32px}
.iv-p .who{flex:1;min-width:0}
.iv-p .n{font-size:13.5px;font-weight:500;color:var(--text)}
.iv-p .e{font-size:12px;color:var(--muted)}
.iv-p .tag{margin-left:6px}
.iv-role{display:inline-flex;align-items:center;gap:3px;padding:4px 6px;font-size:12.5px;color:var(--text-dim);transition:color .2s,background-color .2s}
.iv-role:hover{color:var(--text);background:var(--chip)}
.iv-role .ms{font-size:13px}
.iv-role.owner{pointer-events:none}
.iv-role.owner .ms{display:none}
.iv-p.new{animation:enter .45s var(--ease) both}
.iv-foot{display:flex;justify-content:space-between;gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid var(--line)}
.iv-menu{position:absolute;z-index:7;width:190px;padding:4px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -16px rgba(0,0,0,.35);opacity:0;visibility:hidden;transform:translateY(-4px) scale(.98);transform-origin:top right;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s linear .3s}
.iv-menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .18s ease,transform .3s var(--ease),visibility 0s}
.iv-mi{display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;text-align:left;font-size:13px;color:var(--text);transition:background-color .15s}
.iv-mi:hover{background:var(--chip)}
.iv-mi .d{display:block;font-size:11.5px;color:var(--muted)}
.iv-mi .ms{margin-left:auto;color:var(--accent);opacity:0}
.iv-mi.sel .ms{opacity:1}
.iv-mi.rm{color:var(--danger);border-top:1px solid var(--line);margin-top:2px}

/* ---------- invite ---------- */
{
  const iv = $('#iv'), field = $('#iv-field'), q = $('#iv-q'), chipsEl = $('#iv-chips'), sug = $('#iv-sug'), list = $('#iv-list'), menu = $('#iv-menu'), perm = $('#iv-perm'), send = $('#iv-send');
  const mail = n => n.toLowerCase().split(' ')[0] + '@northwind.co';
  const people = ['Priya Nair','Joanna Kim','Jonas Weber','Ines Duarte','Tom Becker'];
  const ROLES = [['Can edit','Make changes and share'],['Can comment','Leave feedback only'],['Can view','Read only']];
  let access = [{ n:'Sam Rivera', r:'Owner', you:true }, { n:'Maya Chen', r:'Can edit' }, { n:'Oscar Lind', r:'Can view' }];
  let picked = [], matches = [], idx = 0, defRole = 'Can edit', menuFor = null;
  const face = n => AV[n] ? avatar(n) : `<span class="iv-ini">${n[0].toUpperCase()}</span>`;
  function renderList(fresh){
    list.innerHTML = access.map((p, i) => `<div class="iv-p ${fresh && fresh.includes(p.n) ? 'new' : ''}">${face(p.n)}<div class="who"><div class="n">${p.n}${p.you ? ' (you)' : ''}${p.invited ? '<span class="tag">Invited</span>' : ''}</div><div class="e">${p.mail || mail(p.n)}</div></div><button class="iv-role ${p.r === 'Owner' ? 'owner' : ''}" data-i="${i}">${p.r}${ic('expand_more','sm')}</button></div>`).join('');
  }
  function renderChips(){
    chipsEl.innerHTML = picked.map((n, i) => `<span class="iv-chip">${face(n)}${n}<button data-i="${i}" aria-label="Remove ${n}">${ic('close','sm')}</button></span>`).join('');
    send.disabled = !picked.length; q.placeholder = picked.length ? '' : 'Add people by name or email';
  }
  function renderSug(){
    const v = q.value.trim().toLowerCase();
    const taken = new Set([...picked, ...access.map(a => a.n)]);
    matches = people.filter(n => !taken.has(n) && (!v || n.toLowerCase().includes(v) || mail(n).includes(v)));
    if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) && !matches.length) matches = [v];
    idx = 0;
    if (!matches.length){ sug.classList.remove('show'); return; }
    sug.innerHTML = matches.map((n, i) => `<button class="iv-s ${i === 0 ? 'act' : ''}" data-i="${i}">${face(n)}<span><span class="n" style="display:block">${AV[n] ? n : 'Invite ' + n}</span><span class="e">${AV[n] ? mail(n) : 'Send an email invite'}</span></span></button>`).join('');
    sug.style.top = (field.offsetTop + field.offsetHeight + 6) + 'px'; sug.classList.add('show');
  }
  function add(n){ picked.push(n); q.value = ''; renderChips(); renderSug(); Sound.play('select'); q.focus(); }
  q.addEventListener('focus', renderSug);
  q.addEventListener('blur', () => setTimeout(() => sug.classList.remove('show'), 150));
  q.addEventListener('input', () => { renderSug(); Sound.play('stream'); });
  q.addEventListener('keydown', e => {
    if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && matches.length){ e.preventDefault(); idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + matches.length) % matches.length; $$('.iv-s', sug).forEach((b, i) => b.classList.toggle('act', i === idx)); Sound.play('tick'); }
    else if (e.key === 'Enter' && matches[idx]){ e.preventDefault(); add(matches[idx]); }
    else if (e.key === 'Backspace' && !q.value && picked.length){ picked.pop(); renderChips(); renderSug(); Sound.play('tick'); }
  });
  sug.addEventListener('mousedown', e => { const b = e.target.closest('.iv-s'); if (b){ e.preventDefault(); add(matches[+b.dataset.i]); } });
  chipsEl.addEventListener('click', e => { const b = e.target.closest('button'); if (b){ e.preventDefault(); picked.splice(+b.dataset.i, 1); renderChips(); Sound.play('tick'); } });
  function openMenu(btn, forWhat){
    menuFor = forWhat; const cur = forWhat === 'def' ? defRole : access[forWhat].r;
    menu.innerHTML = ROLES.map(r => `<button class="iv-mi ${r[0] === cur ? 'sel' : ''}" data-r="${r[0]}"><span><span style="display:block">${r[0]}</span><span class="d">${r[1]}</span></span>${ic('check','sm')}</button>`).join('') + (forWhat === 'def' ? '' : '<button class="iv-mi rm" data-r="rm">Remove access</button>');
    const ir = iv.getBoundingClientRect(), br = btn.getBoundingClientRect();
    menu.style.left = Math.min(ir.width - 196, br.right - ir.left - 190) + 'px'; menu.style.top = (br.bottom - ir.top + 4) + 'px';
    menu.classList.add('show'); Sound.play('open');
  }
  const closeMenu = () => { menu.classList.remove('show'); menuFor = null; };
  perm.addEventListener('click', e => { e.stopPropagation(); menu.classList.contains('show') && menuFor === 'def' ? closeMenu() : openMenu(perm, 'def'); });
  list.addEventListener('click', e => { const b = e.target.closest('.iv-role'); if (b){ e.stopPropagation(); openMenu(b, +b.dataset.i); } });
  menu.addEventListener('click', e => {
    const b = e.target.closest('.iv-mi'); if (!b) return; const r = b.dataset.r;
    if (menuFor === 'def'){ defRole = r; swapText($('span', perm), r); }
    else if (r === 'rm'){ access.splice(menuFor, 1); renderList(); }
    else { access[menuFor].r = r; renderList(); }
    Sound.play(r === 'rm' ? 'close' : 'select'); closeMenu();
  });
  document.addEventListener('pointerdown', e => { if (menu.classList.contains('show') && !menu.contains(e.target) && !e.target.closest('.iv-role,#iv-perm')) closeMenu(); });
  send.addEventListener('click', () => {
    if (!picked.length) return;
    const names = picked.slice(); picked = []; renderChips(); q.blur(); sug.classList.remove('show');
    send.disabled = true; $('#iv-send-t').innerHTML = '<i class="bt-spin"></i>'; Sound.play('send');
    setTimeout(() => {
      names.forEach(n => access.push({ n, r:defRole, invited:true, mail:AV[n] ? null : n }));
      renderList(names); swapText($('#iv-send-t'), 'Send invite'); Sound.play('done');
      showToast(`Invite sent to ${names.length === 1 ? names[0] : names.length + ' people'}`);
    }, 900);
  });
  $('#iv-link').addEventListener('click', async () => { if (await copyText('https://designme.dev/share/pricing-page-v2')){ Sound.play('copy'); showToast('Link copied'); } });
  renderList(); renderChips();
}
